package com.spidy.servlet;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import com.spidy.util.*;
@WebServlet("/leaderboard") public class LeaderboardServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws IOException,ServletException{try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("SELECT u.username,u.player_level,u.total_xp,(SELECT COUNT(*) FROM mission_submissions m WHERE m.user_id=u.id AND m.is_correct=1) completed FROM users u ORDER BY u.total_xp DESC")){r.setAttribute("players",s.executeQuery());r.getRequestDispatcher("leaderboard.jsp").forward(r,p);}catch(Exception e){r.getSession().setAttribute("msg",e.getMessage());p.sendRedirect("index.jsp");}}}
